DROP TABLE IF EXISTS `t_category`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_category` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `parentid` int NOT NULL DEFAULT '0' COMMENT '二级ID',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '分类名称',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT '分类路径',
  `label` varchar(255) NOT NULL COMMENT '分类辨识',
  `key` varchar(255) NOT NULL COMMENT '分类键值',
  `sort` bigint NOT NULL DEFAULT '0' COMMENT '排序字段',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb3 COMMENT='分类表';
