INSERT INTO `t_sign` VALUES (10000,'bt信息','宝塔信息','&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;nps 服务器IP &lt;/strong&gt;&lt;a href=&quot;http://132.226.22.210:18080/client/list&quot; target=&quot;_blank&quot;&gt;&lt;strong&gt;http://132.226.22.210&lt;/strong&gt;&lt;/a&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;管理地址： &lt;/strong&gt;&lt;a href=&quot;http://132.226.22.210:18080/client/list&quot; target=&quot;_blank&quot;&gt;&lt;strong&gt;http://132.226.22.210:18080/client/list&lt;/strong&gt;&lt;/a&gt;&lt;strong&gt; &lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;账户admin&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;电信 &amp;nbsp;win &amp;nbsp;&lt;/strong&gt;&lt;a href=&quot;http://132.226.22.210:7388/site&quot; target=&quot;_blank&quot;&gt;&lt;strong&gt;http://132.226.22.210:7388/site&lt;/strong&gt;&lt;/a&gt;&lt;strong&gt; &amp;nbsp; cn92527&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;电信云宝塔 &lt;/strong&gt;&lt;a href=&quot;http://132.226.22.210:8088/files&quot; target=&quot;_blank&quot;&gt;&lt;strong&gt;http://132.226.22.210:8088/cn927&lt;/strong&gt;&lt;/a&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;nps服务端 服务器IP &lt;/strong&gt;&lt;a href=&quot;http://132.226.22.210:18080/client/list&quot; target=&quot;_blank&quot;&gt;&lt;strong&gt;http://132.226.22.210&lt;/strong&gt;&lt;/a&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;服务端管理地址： &lt;/strong&gt;&lt;a href=&quot;http://132.226.22.210:18080/client/list&quot; target=&quot;_blank&quot;&gt;&lt;strong&gt;http://132.226.22.210:18080/client/list&lt;/strong&gt;&lt;/a&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;账户cn927&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;NPS文档&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;a href=&quot;https://github.com/ehang-io/nps&quot; target=&quot;_blank&quot;&gt;&lt;strong&gt;https://github.com/ehang-io/nps&lt;/strong&gt;&lt;/a&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;启动&lt;/strong&gt;&lt;span style=&quot;background-color: rgb(225, 60, 57);&quot;&gt;&lt;strong&gt;服务端&lt;/strong&gt;&lt;/span&gt;&lt;strong&gt; &amp;nbsp;安装路径/etc/nps/conf &amp;nbsp; 在nps.conf 手动添加域名-记得在域名管理处解析好&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;sudo nps start&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;客户端 &amp;nbsp;安装路径/root/nps/conf&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;span style=&quot;color: rgb(202, 68, 64); background-color: rgb(249, 242, 244);&quot;&gt;&lt;strong&gt;第一： cd nps&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;span style=&quot;color: rgb(202, 68, 64); background-color: rgb(249, 242, 244);&quot;&gt;&lt;strong&gt;第二 ./npc -server=132.226.22.210:8024 -vkey=test -type=tcp&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;端口开放&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;iptables -P INPUT ACCEPT&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;iptables -P FORWARD ACCEPT&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;iptables -P OUTPUT ACCEPT&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;iptables -F&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;FRP项目&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;&lt;br&gt;重启以后需要开启服务！&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;client客户端&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;cd /usr/local/frp_0.51.3_linux_amd64&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;pkill -9 frpc&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;nohup ./frpc -c frpc.ini &amp;amp;&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;server服务端&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;cd /usr/local/frp_0.51.3_linux_arm64&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;pkill -9 frps&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;nohup ./frps -c frps.ini &amp;amp;&lt;/strong&gt;&lt;/p&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=&quot;text-align: start;&quot;&gt;&lt;br&gt;&lt;/p&gt;',7),(10002,'强盛支出物品','统计','&lt;p&gt;防窥膜/钻石膜- &amp;nbsp; &amp;nbsp;&lt;/p&gt;&lt;p&gt;空调定金800&lt;/p&gt;&lt;p&gt;广告灯箱800 我老婆付了&lt;/p&gt;&lt;p&gt;柜子收银台-12000&lt;/p&gt;&lt;p&gt;发光字 2400&lt;/p&gt;&lt;p&gt;保险柜588&lt;/p&gt;&lt;p&gt;赠品20W头 &amp;nbsp;10个&lt;/p&gt;&lt;p&gt;电脑一套 &amp;nbsp;1350&lt;/p&gt;&lt;p&gt;现金-20000&lt;/p&gt;&lt;p&gt;大概37938&lt;/p&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;',8),(10003,'各大系统镜像源地址','各大系统镜像源地址','&lt;h5 style=&quot;text-align: start;&quot;&gt;&lt;a href=&quot;https://zxmls520.github.io/zxmls/#/?id=ep154-%e5%88%a9%e7%94%a8pve%e8%99%9a%e6%8b%9f%e6%9c%ba%ef%bc%8c%e5%ae%89%e8%a3%85windows%e5%92%8clinux%e7%b3%bb%e7%bb%9f%ef%bc%8c%e5%b9%b6%e4%bc%98%e5%8c%96%e9%85%8d%e7%bd%ae%ef%bc%88aio%e6%89%93%e9%80%a0%e7%ac%ac%e4%ba%8c%e9%9b%86%ef%bc%89&quot; target=&quot;&quot;&gt;&lt;span style=&quot;color: rgb(52, 73, 94);&quot;&gt;&lt;strong&gt;EP154 - 利用PVE虚拟机，安装Windows和Linux系统，并优化配置（AIO打造第二集）&lt;/strong&gt;&lt;/span&gt;&lt;/a&gt;&lt;/h5&gt;&lt;p style=&quot;text-align: start;&quot;&gt;● Windows镜像（MSDN）：&lt;a href=&quot;https://visualstudio.microsoft.com/zh-hans/msdn-platforms&quot; target=&quot;_blank&quot;&gt;https://visualstudio.microsoft.com/zh-hans/msdn-platforms&lt;/a&gt;&lt;/p&gt;&lt;p style=&quot;text-align: start;&quot;&gt;● Windows镜像（仓储站）：&lt;a href=&quot;https://hellowindows.cn/&quot; target=&quot;_blank&quot;&gt;https://hellowindows.cn&lt;/a&gt;&lt;/p&gt;&lt;p style=&quot;text-align: start;&quot;&gt;● Win10LTSC镜像：&lt;a href=&quot;https://pan.quark.cn/s/dac57b63096e&quot; target=&quot;_blank&quot;&gt;https://pan.quark.cn/s/dac57b63096e&lt;/a&gt;&lt;/p&gt;&lt;p style=&quot;text-align: start;&quot;&gt;● VirtIO驱动镜像：&lt;a href=&quot;https://pan.quark.cn/s/fd419d8611bd&quot; target=&quot;_blank&quot;&gt;https://pan.quark.cn/s/fd419d8611bd&lt;/a&gt;&lt;/p&gt;&lt;p style=&quot;text-align: start;&quot;&gt;● Ubuntu（官网）：&lt;a href=&quot;https://cn.ubuntu.com/download&quot; target=&quot;_blank&quot;&gt;https://cn.ubuntu.com/download&lt;/a&gt;&lt;/p&gt;&lt;p style=&quot;text-align: start;&quot;&gt;● Ubuntu20.4镜像：&lt;a href=&quot;https://pan.quark.cn/s/c1bba37ab249&quot; target=&quot;_blank&quot;&gt;https://pan.quark.cn/s/c1bba37ab249&lt;/a&gt;&lt;/p&gt;&lt;p style=&quot;text-align: start;&quot;&gt;● MobaXterm（官网）：&lt;a href=&quot;https://mobaxterm.mobatek.net/&quot; target=&quot;_blank&quot;&gt;https://mobaxterm.mobatek.net&lt;/a&gt;&lt;/p&gt;&lt;p style=&quot;text-align: start;&quot;&gt;● MobaXterm：&lt;a href=&quot;https://pan.quark.cn/s/e269ad2a5ae9&quot; target=&quot;_blank&quot;&gt;https://pan.quark.cn/s/e269ad2a5ae9&lt;/a&gt;&lt;/p&gt;&lt;p style=&quot;text-align: start;&